IPv4 header, 20 bytes without options (each row is 32 bits)

  0       4       8              16      19                      31
 +-------+-------+--------------+-----------------------------------+
 |Version|  IHL  | DSCP |  ECN  |           Total Length            |
 +-------+-------+--------------+-----+-----------------------------+
 |        Identification        |Flags|       Fragment Offset       |
 +---------------+--------------+-----+-----------------------------+
 |     TTL       |   Protocol   |          Header Checksum          |
 +---------------+--------------+-----------------------------------+
 |                       Source Address                             |
 +------------------------------------------------------------------+
 |                    Destination Address                           |
 +------------------------------------------------------------------+
 |                Options (0..40 bytes) + padding                   |
 +------------------------------------------------------------------+

Real header, hex: 45 00 00 73 00 00 40 00 40 11 b8 61 c0 a8 00 01 c0 a8 00 c7
 version 4, IHL 5 (20 bytes), DSCP 0, total length 0x0073 = 115
 ID 0, flags 010 (DF set), offset 0, TTL 0x40 = 64, protocol 0x11 = UDP
 checksum 0xb861, src 192.168.0.1, dst 192.168.0.199

#include <stdint.h>
#include <stddef.h>

/* Internet checksum over `len` bytes (header must have checksum = 0). */
uint16_t ip_checksum(const void *data, size_t len) {
    const uint8_t *p = data;
    uint32_t sum = 0;
    while (len > 1) {                   /* add 16-bit big-endian words */
        sum += (uint32_t)((p[0] << 8) | p[1]);
        p += 2; len -= 2;
    }
    if (len) sum += (uint32_t)(p[0] << 8);   /* odd trailing byte */
    while (sum >> 16)                        /* fold carries back in */
        sum = (sum & 0xFFFF) + (sum >> 16);
    return (uint16_t)~sum;
}

struct ipv4_hdr {
    uint8_t  ver_ihl;      /* (4 << 4) | ihl */
    uint8_t  tos;          /* DSCP << 2 | ECN */
    uint16_t total_len;
    uint16_t id;
    uint16_t flags_frag;   /* flags in top 3 bits, offset in low 13 */
    uint8_t  ttl;
    uint8_t  proto;
    uint16_t checksum;
    uint32_t src, dst;
};
